  "ideas": [
    {
      "id": "I-01",
      "title": "生态—演化反馈中的稀有历史与路径切换",
      "idea": "将生态—演化反馈回路表示为受生态及遗传变化约束的联合时间路径，研究不同罕见历史如何触发系统状态转移，以及主导路径切换如何改变宏观韧性。重点从静态性状—环境关系转向抵达同一生态结果的历史序列及其脆弱性差异。",
      "motivation": "进化生态强调互惠反馈、延迟及结果相对的时间尺度；非平衡统计物理提供以路径而非平均态组织稀有转移的视角。结合后，平均种群规模或平均性状相近的系统仍可能因可达历史不同而具有不同恢复能力。",
      "domains": [
        "Non-equilibrium statistical physics",
        "Evolutionary ecology"
      ],
      "research_question": "种群改造环境而环境改变后续选择时，哪些罕见的联合生态—演化历史触发状态转移？相同平均状态是否可能隐藏不同的转移路径和恢复能力？",
      "conceptual_move": "把生态—演化互惠因果环转写为路径空间中受约束的竞争历史，并把韧性问题从局部平均恢复率移到离开状态的历史组织方式。",
      "why_this_crossing_matters": "它使时间顺序、延迟反馈与转移历史成为核心解释对象，并提出相同终态可由不同历史到达、因而对扰动呈现不同脆弱性的研究方向。",
      "concept_mapping": [
        {
          "source_concept": "受守恒关系约束的时空路径及其稀有事件代价",
          "target_counterpart": "种群数量、遗传性状与被种群改造的环境组成的联合轨迹",
          "transfer": "以整段可行轨迹而非单时点状态解释转移，并比较导致相同结果的不同历史",
          "where_analogy_may_break": "遗传漂变、离散种群事件和生态噪声不必满足扩散型连续介质假设；有效路径代价也未必是热力学作用量。"
        },
        {
          "source_concept": "大偏差路径集合中主导历史类别的切换",
          "target_counterpart": "不同反馈链路或演化响应顺序主导的群落跃迁",
          "transfer": "将韧性变化理解为主导转移历史改变，而不只看平均参数平滑变化",
          "where_analogy_may_break": "有限种群、有限观测窗及环境非平稳性可能只产生平滑交叉，而非严格的路径相变。"
        }
      ]
    },
    {
      "id": "I-02",
      "title": "免疫记忆作为具有情境约束的分布式配置制度",
      "idea": "将免疫记忆视为由携带不同历史、组织可达性和响应倾向的细胞构成的分布式配置制度，研究局部信号、募集、迁移与存活规则如何从不完整的威胁信息形成整体响应，以及这些规则如何分配有限组织机会并产生保护或病理。这里的机制是因果性局部响应规则，不假设细胞具有经济主体式的意识或策略动机。",
      "motivation": "免疫学描述记忆细胞状态、暴露历史和组织位置的异质性；机制设计关注分散信息如何经规则映射为配置结果。交叉后，问题由某类细胞是否有效转为局部规则如何汇总信息、配置资源并放大群体级保护—病理权衡。",
      "domains": [
        "Immunology and immune memory",
        "Economics and mechanism design"
      ],
      "research_question": "免疫系统如何在克隆特异性记忆、训练性广谱反应和组织驻留之间配置细胞、空间与响应资源，以应对复发威胁并限制局部持续损伤？",
      "conceptual_move": "将细胞异质性重述为分散信息与局部资源配置问题，研究没有全局控制者时，局部响应规则如何形成组织级结果。",
      "why_this_crossing_matters": "这把免疫记忆的状态、空间与历史依赖整合为规则如何塑造群体配置的问题，并将组织位点和细胞可塑性视为影响响应机会及病理风险的结构条件。",
      "concept_mapping": [
        {
          "source_concept": "在分散私有信息下由规则映射行动或报告到配置结果",
          "target_counterpart": "带有不同抗原经历、表观遗传历史和组织位置的细胞所触发的局部信号与募集规则",
          "transfer": "研究局部规则如何从不完整威胁信息形成组织级响应，而不预设全局控制者",
          "where_analogy_may_break": "细胞不是偏好最大化主体；信号转导不等于策略性报告，信息可能体现为物理可达性或分子状态。"
        },
        {
          "source_concept": "机制规则可能分配优势，制度约束会排除某些形式上可行的配置",
          "target_counterpart": "组织结构和迁移约束对驻留记忆、循环细胞及训练性反应的空间机会分配",
          "transfer": "把组织位点与可塑性纳入响应机会和病理风险的结构解释",
          "where_analogy_may_break": "组织位点并非可自由转让的资源；迁移和占位受发育、黏附及生理限制。"
        }
      ]
    },
    {
      "id": "I-03",
      "title": "生态位构建的制度演化与可实施性",
      "idea": "将生态位构建纳入机制的动态结果：参与者的行动改变共同资源、栖息地或选择压力，这些环境变化再重塑未来行动的收益与可行集合。研究静态激励相容和稳定性如何扩展到规则—环境—未来激励的反馈，以及短期稳定配置如何可能侵蚀长期生态可行性。",
      "motivation": "进化生态解释行动与环境如何互相塑造，但未必刻画集体配置的可实施性；机制设计刻画规则和偏离，却常把环境视为给定。联结两者可区分无人愿意偏离与群体长期维持良好生态条件这两个目标。",
      "domains": [
        "Evolutionary ecology",
        "Economics and mechanism design"
      ],
      "research_question": "当行动者通过生态位构建改变共同环境时，哪些规则能稳定地产生可持续资源配置？环境内生变化时，激励相容和稳定性应如何重新表述？",
      "conceptual_move": "从固定偏好和可行集合上的机制，转向由行动共同生产并会反过来改变未来行动条件的生态制度。",
      "why_this_crossing_matters": "它能揭示短期稳定分配如何经环境反馈侵蚀长期可行性，并将局部信息、可行偏离和跨期生态结果放入同一问题结构。",
      "concept_mapping": [
        {
          "source_concept": "生态—演化互惠回路：群体改变环境，环境改变后续选择",
          "target_counterpart": "制度参与者的行动改变共同资源或栖息地，继而改变未来收益、能力和可选行动",
          "transfer": "把环境状态作为机制的内生状态，研究规则的长期结果如何包括其自身重塑的生态条件",
          "where_analogy_may_break": "环境变化可能缓慢、空间异质，且受非参与物种影响，不能简化为参与者有意选择的结果。"
        },
        {
          "source_concept": "稳定配置中不存在相互有利的阻挡偏离",
          "target_counterpart": "参与者采取会改变未来资源条件的单方或联合行动序列",
          "transfer": "将偏离扩展为会改写未来环境与可行集合的行动序列",
          "where_analogy_may_break": "动态生态后果未必有共同时间尺度或清晰偏好排序；有利与否依赖跨代福利及生态价值定义。"
        },
        {
          "source_concept": "私人信息下的激励相容与可实施性",
          "target_counterpart": "掌握局部生态信息且能改变他人环境与收益的行动者",
          "transfer": "研究局部知识如何经规则转化为生态管理，而不假设中央设计者观察完整状态",
          "where_analogy_may_break": "生态反馈也可由无意行为、突变和非人类过程产生，不都能表示为可报告的私人类型或策略行动。"
        }
      ]
    }
  ]
}

